<?php $edit=$payment!==null;$val=static fn($k,$d='')=>e((string)($payment[$k]??$d));?><div class="page-header mb-4"><h2 class="page-title"><?=$edit?'تعديل مسودة الدفعة':'إضافة دفعة مقاول باطن'?></h2></div><div class="alert alert-info">المتاح للدفع حاليًا: <strong id="available-payment" data-value="<?=e($summary['available_payment_amount'])?>"><?=e($summary['available_payment_amount'])?></strong></div><form method="post" id="payment-form" action="<?=$edit?'/subcontract-payments/'.(int)$payment['id'].'/edit':'/subcontracts/'.(int)$subcontract['id'].'/payments'?>"><input type="hidden" name="_token" value="<?=e($csrfToken)?>"><div class="card"><div class="card-body"><div class="row g-3"><div class="col-md-4"><label class="form-label required">تاريخ الدفع</label><input class="form-control" type="date" name="payment_date" required value="<?=$val('payment_date',date('Y-m-d'))?>"></div><div class="col-md-4"><label class="form-label required">المبلغ</label><input id="payment-amount" class="form-control" type="number" min="0.01" step="0.01" name="amount" required value="<?=$val('amount')?>"><div id="amount-warning" class="invalid-feedback">المبلغ يتجاوز المتاح للدفع.</div></div><div class="col-md-4"><label class="form-label required">طريقة الدفع</label><select class="form-select" name="payment_method" required><?php foreach(['cash'=>'نقدي','bank_transfer'=>'تحويل بنكي','cheque'=>'شيك','other'=>'أخرى']as$k=>$v):?><option value="<?=$k?>" <?=($payment['payment_method']??'')===$k?'selected':''?>><?=$v?></option><?php endforeach;?></select></div><div class="col-md-6"><label class="form-label">الرقم المرجعي</label><input class="form-control" maxlength="190" name="reference_number" value="<?=$val('reference_number')?>"></div><div class="col-md-6"><label class="form-label">ملاحظات</label><textarea class="form-control" name="notes"><?=$val('notes')?></textarea></div></div></div><div class="card-footer text-end"><button class="btn btn-primary">حفظ المسودة</button></div></div></form><script src="/assets/js/modules/subcontract-payment-form.js" defer></script>
